diff --git a/src/core/project.ts b/src/core/project.ts
index 76d1577..165daf9 100644
--- a/src/core/project.ts
+++ b/src/core/project.ts
@@ -6,12 +6,48 @@ export interface Record {
   warns: readonly string[];
 }

+const semanticKey = (text: string): string => {
+  const normalized = text.toLowerCase();
+  const concepts = new Set<string>();
+
+  // Map phrases and keywords to semantic concepts
+  if (/stateful|infrastructure|operator|always-on|operational|cache service|managed/.test(normalized)) {
+    concepts.add("operational-burden");
+  }
+  if (/ops|operate|running|component|service|tier/.test(normalized)) {
+    concepts.add("operational-burden");
+  }
+
+  // Return sorted concepts to ensure deterministic grouping
+  return Array.from(concepts).sort().join("|") || "other";
+};
+
 export const project = (records: readonly Record[]): string => {
   const lines: string[] = [];
+
   for (const record of records) {
-    for (const entry of record.ruledOut) lines.push(`- ruled out: ${entry}`);
-    for (const limit of record.limits) lines.push(`- limit: ${limit}`);
-    for (const warn of record.warns) lines.push(`- warn: ${warn}`);
+    const dedupLimits = deduplicateBySemantics(record.limits);
+    const dedupRuledOut = deduplicateBySemantics(record.ruledOut);
+    const dedupWarns = deduplicateBySemantics(record.warns);
+
+    for (const entry of dedupRuledOut) lines.push(`- ruled out: ${entry}`);
+    for (const limit of dedupLimits) lines.push(`- limit: ${limit}`);
+    for (const warn of dedupWarns) lines.push(`- warn: ${warn}`);
   }
   return lines.join("\n");
 };
+
+const deduplicateBySemantics = (entries: readonly string[]): string[] => {
+  const seen = new Map<string, string>();
+  const result: string[] = [];
+
+  for (const entry of entries) {
+    const key = semanticKey(entry);
+    if (!seen.has(key)) {
+      seen.set(key, entry);
+      result.push(entry);
+    }
+  }
+
+  return result;
+};
